package chess; public class Board { private final Piece[][] cells=new Piece[8][8]; public Piece get(Position p){return cells[p.row()][p.col()];} public void set(Position p,Piece x){cells[p.row()][p.col()]=x;} public boolean clear(Position a,Position b){int dr=Integer.signum(b.row()-a.row()),dc=Integer.signum(b.col()-a.col());int r=a.row()+dr,c=a.col()+dc;while(r!=b.row()||c!=b.col()){if(cells[r][c]!=null)return false;r+=dr;c+=dc;}return true;} public boolean move(Position a,Position b){Piece p=get(a);if(p==null||!b.valid()||!p.canMove(a,b,this))return false;Piece q=get(b);if(q!=null&&q.color()==p.color())return false;set(b,p);set(a,null);return true;} }